import React, { ReactNode } from "react";

type ThemeMode = "light" | "dark";

type ColorModeContextType = {
  mode: ThemeMode,
};
export const ColorModeContext = React.createContext<ColorModeContextType | null>(null);

type ColorModeProviderProps = {
  mode: string;
  children: ReactNode;
};

/* This component allows container components (such as a dark header) to provide a color mode to their children. */
export default function ColorModeProvider({
  children,
  mode = "light",
}: ColorModeProviderProps) {
  return (
    <ColorModeContext.Provider value={{ mode: mode as ThemeMode }}>
      {children}
    </ColorModeContext.Provider>
  );
}

/* This hook either returns the default mode or a color mode if a parent use a ColorModeProvider.
Therefore it must be used by all components instead of useTheme (and is used by createUseStyles anyway). */
export const useColorMode = () => {
  const outerMode = React.useContext(ColorModeContext);
  return outerMode ? outerMode.mode : "light";
};
